/* Consumables use halfwords in the original 60-byte array. Equipment remains
 * u32. Ordering matches the address catalog generated by generate-shop-catalog.
 * These instructions are assembled at export, never shipped as machine code.
 */
.set noreorder
.set noat
    sh $a1, 0($s2)             /* 1978d8: splitter store */
    addiu $s2, $s2, 2          /* 1978dc: splitter stride */
    lhu $v0, -0x5f28($v0)      /* 197958: first-entry presence */
    sll $v0, $v0, 1           /* 197da4: selection index */
    lhu $v1, -0x5f28($v1)      /* 197db0: selection ID */
    sll $v0, $v0, 1           /* 198020: purchase index */
    lhu $a1, -0x5f28($a1)      /* 19802c: purchase ID */
    sll $v0, $s1, 1           /* 198cdc: name index */
    lhu $s0, -0x5f28($s0)      /* 198ce8: name ID */
    sll $v0, $s1, 1           /* 198f58: price index */
    lhu $v1, 0($v0)           /* 198f60: price ID */
    sll $v0, $v0, 1           /* 199550: detail index */
    lhu $s0, -0x5f28($s0)      /* 19955c: detail ID */
    sll $v0, $v0, 1           /* 19a330: use index */
    lhu $s1, -0x5f28($s1)      /* 19a33c: use ID */
    nop                       /* 19795c: keep the final consumable category */
    jal lc_shop_selection_guard /* 197d6c */
    and $a0, $v0, $a0          /* 197d70: pressed-button mask in delay slot */
    beq $v0, $zero, .+420      /* 197d74: cancel/navigation at197f18 */
    nop                       /* unused assembler padding */
